import{_ as s,C as a,o as r,c as i,j as t,a as o,E as p,a5 as h}from"./chunks/framework.DtspaGiy.js";const y=JSON.parse('{"title":"Print","description":"","frontmatter":{},"headers":[],"relativePath":"guide/print.md","filePath":"guide/print.md"}'),d={name:"guide/print.md"};function l(g,e,c,u,m,f){const n=a("Shot");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"print",tabindex:"-1"},[o("Print "),t("a",{class:"header-anchor",href:"#print","aria-label":'Permalink to "Print"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("Press "),t("code",null,"Mod"),o(),t("code",null,"P"),o(" and then "),t("code",null,"Enter"),o(", and your whole document goes to your system's print dialog, ready for the printer. That's all most prints need. Blank's print dialog shows the pages as they'll come out of the printer, so you can check them before any paper is used.")],-1)),p(n,{src:"print.gif",alt:"Mod P opens the print dialog with the first page as it prints, in ink on white paper; Page Down leafs through the pages. Under More settings, 2 pages per sheet puts two pages side by side on a sheet turned sideways; Custom pages 2-4 leaves out the first page; PDF file turns the button into Save PDF…"}),e[2]||(e[2]=h('<h2 id="what-prints" tabindex="-1">What prints <a class="header-anchor" href="#what-prints" aria-label="Permalink to &quot;What prints {#what-prints}&quot;">​</a></h2><p>The preview on the left shows only the pages that will print, one sheet at a time, in ink on white paper whatever theme you use. They&#39;re the same pages you see on the screen and in your PDF, with your <a href="./pages#headers-and-footers">header, footer and page numbers</a>. Placeholders and spelling marks stay on the screen. <code>‹</code> <code>›</code> or <code>Page Up</code> and <code>Page Down</code> leaf through the sheets, and the line at the bottom left sums it up, e.g. <em>3 pages on 2 sheets, 2 copies</em>.</p><ul><li><strong>Copies:</strong> type a number, click <code>−</code> and <code>+</code>, or press <code>↑</code> and <code>↓</code> in the field. From two copies on, <strong>Keep each copy together</strong> prints each copy whole before the next.</li><li><strong>Pages:</strong> <strong>All</strong>, the <strong>Current page</strong> (the one your cursor is on; point at it to see which), or <strong>Custom</strong>: type numbers and ranges, like <code>1-3, 5</code>. <code>4-</code> prints from page 4 to the end, and <code>-2</code> the first two pages. If a page isn&#39;t there, Blank tells you as soon as you stop typing, and waits until the pages are right.</li><li><strong>More settings:</strong><ul><li><strong>Pages per sheet:</strong> 1, 2 or 4. Two pages go side by side on a sheet turned sideways; four go in two rows.</li><li><strong>Scale:</strong> <strong>Actual size</strong> prints your pages as you see them. <strong>Fit to paper</strong> shrinks or grows them to fill the paper the printer holds, which helps when it isn&#39;t your document&#39;s paper.</li><li><strong>Paper:</strong> your document&#39;s <a href="./pages#page-setup">page setup</a> decides the paper. <strong>Page setup…</strong> takes you there.</li></ul></li></ul><p>Blank remembers the destination, pages per sheet and scale, and whether <strong>More settings</strong> is open. Copies and pages start over each time.</p><h2 id="the-printer" tabindex="-1">The printer and its options <a class="header-anchor" href="#the-printer" aria-label="Permalink to &quot;The printer and its options {#the-printer}&quot;">​</a></h2><p><strong>Print…</strong> opens your system&#39;s print dialog next. There you choose the printer and what it offers, like printing on both sides, in color or from another tray. Blank&#39;s dialog has already chosen what only Blank knows: the pages, how they fall on the sheets, and how many copies.</p><h2 id="pdf" tabindex="-1">A PDF instead <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;A PDF instead {#pdf}&quot;">​</a></h2><p>Choose <strong>PDF file</strong> as the destination and the button turns into <strong>Save PDF…</strong>: Blank saves the pages you chose as the same PDF that <a href="./files#pdf">Export as PDF</a> writes, only with fewer pages if you picked some. Its bookmarks and table of contents links lead only to pages that are in it. <code>Mod</code> <code>Alt</code> <code>P</code> still exports the whole document.</p><p>If printing doesn&#39;t work, Blank opens its print dialog again, says why, and is ready to save a PDF you can print from another app.</p><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know {#good-to-know}&quot;">​</a></h2><ul><li><strong>Linux:</strong> printing goes through your desktop&#39;s print service (the print portal), in the Snap too. Desktops without it can&#39;t print from Blank; save a PDF and print it from another app instead. The system doesn&#39;t tell Blank the printer&#39;s name, so Blank says <em>Sent 3 pages to the printer</em>.</li><li><strong>Windows:</strong> Windows&#39; print dialog doesn&#39;t take the copies from Blank, so set them again there. It doesn&#39;t tell Blank which paper the printer holds either, so to fit the pages to it, use the scaling in Windows&#39; print dialog. And it doesn&#39;t tell Blank whether you printed, so Blank says nothing afterwards.</li><li><strong>macOS:</strong> the print panel opens on top of Blank and shows the copies you chose.</li><li>Printing needs Blank&#39;s page layout. If it couldn&#39;t start or stopped working, Blank shows your text without pages and can&#39;t print until you restart it.</li></ul>',11))])}const k=s(d,[["render",l]]);export{y as __pageData,k as default};
